public class MarketProduct {
    private String name;
    private double price;
    private boolean organic;
    private String season;
    private String vendor;

    public MarketProduct(String name, double price, boolean organic, String season, String vendor) {
        this.name = name;
        this.price = price;
        this.organic = organic;
        this.season = season;
        this.vendor = vendor;
    }

    public String getName() {
        return name;
    }

    public double getPrice() {
        return price;
    }

    public boolean isOrganic() {
        return organic;
    }

    public String getSeason() {
        return season;
    }

    public String getVendor() {
        return vendor;
    }

    @Override
    public String toString() {
        return name + " ($" + String.format("%.2f", price) + ", " + vendor + ")";
    }
}
